      try {
        if (showLoading) {
          setIsLoading(true);
        }
        setError(null);
        const selectedProjectName = projects.find(p => p.id === selectedProjectId)?.name || '';
        if (!selectedProjectName) {
          setTickets([]);
          if (showLoading) {
            setIsLoading(false);
          }
          return;
