    fetchTickets(isNewProject);

    // Poll for updates every 30 seconds, only when tab is visible
    const startPolling = () => {
      if (document.visibilityState === 'visible') {
        interval = setInterval(() => {
          if (document.visibilityState === 'visible') {
            fetchTickets(false); // Don't show loading during polling
          }
        }, 30000);
      }
